(function(){
"use strict";
const rows=[{"id":"ganjoor-hafez-1","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"الا یا ایها الساقی ادر کأسا و ناولها\r\nکه عشق آسان نمود اول ولی افتاد مشکل ها\r\nبه بوی نافه ای کآخر صبا زان طره بگشاید\r\nز تاب جعد مشکینش چه خون افتاد در دل ها\r\nمرا در منزل جانان چه امن عیش چون هر دم\r\nجرس فریاد می دارد که بربندید محمل ها\r\nبه می سجاده رنگین کن گرت پیر مغان گوید\r\nکه سالک بی خبر نبود ز راه و رسم منزل ها\r\nشب تاریک و بیم موج و گردابی چنین هایل\r\nکجا دانند حال ما سبک باران ساحل ها\r\nهمه کارم ز خودکامی به بدنامی کشید آخر\r\nنهان کی ماند آن رازی کزو سازند محفل ها\r\nحضوری گر همی خواهی از او غایب مشو حافظ\r\nمتیٰ ما تلق من تهویٰ دع الدنیا و اهملها","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh1"},{"id":"ganjoor-hafez-2","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"صلاح کار کجا و من خراب کجا\r\nببین تفاوت ره کز کجاست تا به کجا\r\nدلم ز صومعه بگرفت و خرقه سالوس\r\nکجاست دیر مغان و شراب ناب کجا\r\nچه نسبت است به  رندی صلاح و تقوا را\r\nسماع وعظ کجا نغمه رباب کجا\r\nز روی دوست دل دشمنان چه دریابد\r\nچراغ مرده کجا شمع آفتاب کجا\r\nچو کحل بینش ما خاک آستان شماست\r\nکجا رویم بفرما ازین جناب کجا\r\nمبین به سیب زنخدان که چاه در راه است\r\nکجا همی  روی ای دل بدین شتاب کجا\r\nبشد که یاد خوشش باد روزگار وصال\r\nخود آن کرشمه کجا رفت و آن عتاب کجا\r\nقرار و خواب ز حافظ طمع مدار ای دوست\r\nقرار چیست صبوری کدام و خواب کجا","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh2"},{"id":"ganjoor-hafez-3","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"اگر آن ترک شیرازی به   دست  آرد دل ما را\r\nبه خال هندویش بخشم سمرقند و بخارا را\r\nبده ساقی می باقی که در جنت نخواهی یافت\r\nکنار آب رکناباد و گل گشت مصلا را\r\nفغان کاین لولیان شوخ شیرین کار شهرآشوب\r\nچنان بردند صبر از دل که ترکان خوان یغما را\r\nز عشق ناتمام ما جمال یار مستغنی  است\r\nبه آب و رنگ و خال و خط چه حاجت روی زیبا را\r\nمن از آن حسن روزافزون که یوسف داشت دانستم\r\nکه عشق از پرده عصمت برون آرد زلیخا را\r\nاگر دشنام فرمایی و گر نفرین دعا گویم\r\nجواب تلخ می زیبد لب لعل شکرخا را\r\nنصیحت گوش کن جانا که از جان دوست تر دارند\r\nجوانان سعادتمند پند پیر دانا را\r\nحدیث از مطرب و می گو و راز دهر کمتر جو\r\nکه کس نگشود و نگشاید به حکمت این معما را\r\nغزل گفتی و در سفتی بیا و خوش بخوان حافظ\r\nکه بر نظم تو افشاند فلک عقد ثریا را","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh3"},{"id":"ganjoor-hafez-4","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"صبا به لطف بگو آن غزال رعنا را\r\nکه سر به کوه و بیابان تو داده ای ما را\r\nشکر فروش که عمرش دراز باد چرا\r\nتفقدی نکند طوطی شکرخا را\r\nغرور حسنت اجازت مگر نداد ای گل\r\nکه پرسشی نکنی عندلیب شیدا را\r\nبه خلق و لطف توان کرد صید اهل نظر\r\nبه بند و دام نگیرند مرغ دانا را\r\nندانم از چه سبب رنگ آشنایی نیست\r\nسهی قدان سیه  چشم ماه سیما را\r\nچو با حبیب نشینی و باده پیمایی\r\nبه یاد دار محبان بادپیما را\r\nجز این قدر نتوان گفت در جمال تو عیب\r\nکه وضع مهر و وفا نیست روی زیبا را\r\nدر آسمان نه عجب گر به گفته حافظ\r\nسرود زهره به رقص آورد مسیحا را","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh4"},{"id":"ganjoor-hafez-5","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"دل می رود ز دستم صاحب دلان خدا را\r\nدردا که راز پنهان خواهد شد آشکارا\r\nکشتی شکستگانیم ای باد شرطه برخیز\r\nباشد که باز بینم دیدار آشنا را\r\nده روزه مهر گردون افسانه است و افسون\r\nنیکی به جای یاران فرصت شمار یارا\r\nدر حلقه گل  و مل خوش خواند دوش بلبل\r\nهات الصبوح هبوا یا ایها السکارا\r\nای صاحب کرامت شکرانه سلامت\r\nروزی تفقدی کن درویش بی نوا را\r\nآسایش دو گیتی تفسیر این دو حرف است\r\nبا دوستان مروت با دشمنان مدارا\r\nدر کوی نیک نامی ما را گذر ندادند\r\nگر تو نمی پسندی تغییر کن قضا را\r\nآن تلخ وش که صوفی ام الخبایثش خواند\r\nاشهیٰ لنا و احلیٰ من قبلة العذارا\r\nهنگام تنگ دستی در عیش کوش و مستی\r\nکاین کیمیای هستی قارون کند گدا را\r\nسرکش مشو که چون شمع از غیرتت بسوزد\r\nدلبر که در کف او موم است سنگ خارا\r\nآیینه سکندر جام می است بنگر\r\nتا بر تو عرضه دارد احوال ملک دارا\r\nخوبان پارسی گو بخشندگان عمرند\r\nساقی بده بشارت رندان پارسا را\r\nحافظ به خود نپوشید این خرقه می آلود\r\nای شیخ پاک دامن معذور دار ما را","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh5"},{"id":"ganjoor-hafez-6","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"به ملازمان سلطان که رساند این دعا را\r\nکه به شکر پادشاهی ز نظر مران گدا را\r\nز رقیب دیوسیرت به خدای خود پناهم\r\nمگر آن شهاب ثاقب مددی دهد خدا را\r\nمژه ی سیاهت ار کرد به خون ما اشارت\r\nز فریب او بیندیش و غلط مکن نگارا\r\nدل عالمی بسوزی چو عذار برفروزی\r\nتو از این چه سود داری که نمی کنی مدارا\r\nهمه شب در این امیدم که نسیم صبحگاهی\r\nبه پیام آشنایان بنوازد آشنا را\r\nچه قیامت است جانا که به عاشقان نمودی\r\nدل و جان فدای رویت بنما عذار ما را\r\nبه خدا که جرعه ای ده تو به حافظ سحرخیز\r\nکه دعای صبحگاهی اثری کند شما را","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh6"},{"id":"ganjoor-hafez-7","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"صوفی بیا که آینه صافی ست جام را\r\nتا بنگری صفای می لعل فام را\r\nراز درون پرده ز رندان مست پرس\r\nکاین حال نیست زاهد عالی مقام را\r\nعنقا شکار کس نشود دام بازچین\r\nکآنجا همیشه باد به دست است دام را\r\nدر بزم دور یک دو قدح درکش و برو\r\nیعنی طمع مدار وصال مدام را\r\nای دل شباب رفت و نچیدی گلی ز عیش\r\nپیرانه  سر مکن هنری ننگ و نام را\r\nدر عیش نقد کوش که چون آبخور نماند\r\nآدم بهشت روضه دارالسلام را\r\nما را بر آستان تو بس حق خدمت است\r\nای خواجه بازبین به ترحم غلام را\r\nحافظ مرید جام می است ای صبا برو\r\nوز بنده بندگی برسان شیخ جام را","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh7"},{"id":"ganjoor-hafez-8","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"ساقیا برخیز و درده جام را\r\nخاک بر سر کن غم ایام را\r\nساغر می بر کفم نه تا ز بر\r\nبرکشم این دلق ازرق فام را\r\nگرچه بدنامی ست نزد عاقلان\r\nما نمی خواهیم ننگ و نام را\r\nباده درده چند از این باد غرور\r\nخاک بر سر نفس نافرجام را\r\nدود آه سینه نالان من\r\nسوخت این افسردگان خام را\r\nمحرم راز دل شیدای خود\r\nکس نمی بینم ز خاص و عام را\r\nبا دلارامی مرا خاطر خوش است\r\nکز دلم یک باره برد آرام را\r\nننگرد دیگر به سرو اندر چمن\r\nهرکه دید آن سرو سیم اندام را\r\nصبر کن حافظ به سختی روز و شب\r\nعاقبت روزی بیابی کام را","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh8"},{"id":"ganjoor-hafez-9","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"رونق عهد شباب است دگر بستان را\r\nمی رسد مژده گل بلبل خوش الحان را\r\nای صبا گر به جوانان چمن باز رسی\r\nخدمت ما برسان سرو و گل و ریحان را\r\nگر چنین جلوه کند مغبچه باده فروش\r\nخاک روب در میخانه کنم مژگان را\r\nای که بر مه کشی از عنبر سارا چوگان\r\nمضطرب حال مگردان من سرگردان را\r\nترسم این قوم که بر دردکشان می خندند\r\nدر سر کار خرابات کنند ایمان را\r\nیار مردان خدا باش که در کشتی نوح\r\nهست خاکی که به آبی نخرد طوفان را\r\nبرو از خانه گردون به در و نان مطلب\r\nکآن سیه کاسه در آخر بکشد مهمان را\r\nهر که را خوابگه آخر مشتی خاک است\r\nگو چه حاجت که به افلاک کشی ایوان را\r\nماه کنعانی من مسند مصر آن تو شد\r\nوقت آن است که بدرود کنی زندان را\r\nحافظا می خور و رندی کن و خوش باش ولی\r\nدام تزویر مکن چون دگران قرآن را","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh9"},{"id":"ganjoor-hafez-10","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"دوش از مسجد سوی میخانه آمد پیر ما\r\nچیست یاران طریقت بعد از این تدبیر ما\r\nما مریدان روی سوی قبله چون آریم چون\r\nروی سوی خانه خمار دارد پیر ما\r\nدر خرابات طریقت ما به هم منزل شویم\r\nکاین چنین رفته  است در عهد ازل تقدیر ما\r\nعقل اگر داند که دل در بند زلفش چون خوش است\r\nعاقلان دیوانه گردند از پی زنجیر ما\r\nروی خوبت آیتی از لطف بر ما کشف کرد\r\nزآن زمان جز لطف و خوبی نیست در تفسیر ما\r\nبا دل سنگینت آیا هیچ درگیرد شبی\r\nآه آتشناک و سوز سینه شبگیر ما\r\nتیر آه ما ز گردون بگذرد حافظ خموش\r\nرحم کن بر جان خود پرهیز کن از تیر ما","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh10"},{"id":"ganjoor-hafez-11","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"ساقی به نور باده برافروز جام ما\r\nمطرب بگو که کار جهان شد به کام ما\r\nما در پیاله عکس رخ یار دیده ایم\r\nای بی خبر ز لذت شرب مدام ما\r\nهرگز نمیرد آن که دلش زنده شد به عشق\r\nثبت است بر جریده عالم دوام ما\r\nچندان بود کرشمه و ناز سهی قدان\r\nکآید به جلوه سرو صنوبرخرام ما\r\nای باد اگر به گلشن احباب بگذری\r\nزنهار عرضه ده بر جانان پیام ما\r\nگو نام ما ز یاد به عمدا چه می بری\r\nخود آید آن که یاد نیاری ز نام ما\r\nمستی به چشم شاهد دلبند ما خوش است\r\nزآن رو سپرده اند به مستی زمام ما\r\nترسم که صرفه ای نبرد روز بازخواست\r\nنان حلال شیخ ز آب حرام ما\r\nحافظ ز دیده دانه اشکی همی فشان\r\nباشد که مرغ وصل کند قصد دام ما\r\nدریای اخضر فلک و کشتی هلال\r\nهستند غرق نعمت حاجی قوام ما","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh11"},{"id":"ganjoor-hafez-12","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"ای فروغ ماه حسن  از روی رخشان شما\r\nآب روی خوبی از چاه زنخدان شما\r\nعزم دیدار تو دارد جان بر لب آمده\r\nباز گردد یا برآید چیست فرمان شما\r\nکس به دور نرگست طرفی نبست از عافیت\r\nبه که نفروشند مستوری به مستان شما\r\nبخت خواب آلود ما بیدار خواهد شد مگر\r\nزان که زد بر دیده آبی روی رخشان شما\r\nبا صبا همراه بفرست از رخت گل دسته ای\r\nبو که بویی بشنویم از خاک بستان شما\r\nعمرتان باد و مراد ای ساقیان بزم جم\r\nگرچه جام ما نشد پر می به دوران شما\r\nدل خرابی می کند دلدار را آگه کنید\r\nزینهار ای دوستان  جان من و جان شما\r\nکی دهد دست این غرض یا رب که همدستان شوند \r\nخاطر مجموع ما زلف پریشان شما\r\nدور دار از خاک و خون دامن چو بر ما بگذری\r\nکاندر این ره کشته بسیارند قربان شما\r\nمی کند حافظ دعایی بشنو آمینی بگو\r\nروزی ما باد لعل شکرافشان شما\r\nای صبا با ساکنان شهر یزد از ما بگو\r\nکای سر حق ناشناسان گوی چوگان شما\r\nگرچه دوریم از بساط قرب  همت دور نیست\r\nبنده شاه شماییم و ثناخوان شما\r\nای شهنشاه بلند اختر  خدا را همتی\r\nتا ببوسم همچو اختر خاک ایوان شما","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh12"},{"id":"ganjoor-hafez-13","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"می دمد صبح و کله بست سحاب\r\nالصبوح الصبوح یا اصحاب\r\nمی چکد ژاله بر رخ لاله\r\nالمدام المدام یا احباب\r\nمی وزد از چمن نسیم بهشت\r\nهان بنوشید دم به دم می ناب\r\nتخت زمرد زده است گل به چمن\r\nراح چون لعل آتشین دریاب\r\nدر میخانه بسته اند دگر\r\nافتتح یا مفتح الابواب\r\nلب و دندانت را حقوق نمک\r\nهست بر جان و سینه های کباب\r\nاین چنین موسمی عجب باشد\r\nکه ببندند میکده به شتاب\r\nبر رخ ساقی پری پیکر\r\nهمچو حافظ بنوش باده ناب","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh13"},{"id":"ganjoor-hafez-14","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"گفتم ای سلطان خوبان رحم کن بر این غریب\r\nگفت در دنبال دل ره گم کند مسکین غریب\r\nگفتمش مگذر زمانی گفت معذورم بدار\r\nخانه پروردی چه تاب آرد غم چندین غریب\r\nخفته بر سنجاب شاهی نازنینی را چه غم\r\nگر ز خار و خاره سازد بستر و بالین غریب\r\nای که در زنجیر زلفت جای چندین آشناست\r\nخوش فتاد آن خال مشکین بر رخ رنگین غریب\r\nمی نماید عکس می در رنگ روی مه وشت\r\nهمچو برگ ارغوان بر صفحه نسرین غریب\r\nبس غریب افتاده است آن مور خط گرد رخت\r\nگرچه نبود در نگارستان خط مشکین غریب\r\nگفتم ای شام غریبان طره شبرنگ تو\r\nدر سحرگاهان حذر کن چون بنالد این غریب\r\nگفت حافظ آشنایان در مقام حیرتند\r\nدور نبود گر نشیند خسته و مسکین غریب","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh14"},{"id":"ganjoor-hafez-15","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"ای شاهد قدسی که کشد بند نقابت\r\nوی مرغ بهشتی که دهد دانه و آبت\r\nخوابم بشد از دیده در این فکر جگرسوز\r\nکآغوش که شد منزل آسایش و خوابت\r\nدرویش نمی پرسی و ترسم که نباشد\r\nاندیشه آمرزش و پروای ثوابت\r\nراه دل عشاق زد آن چشم خماری\r\nپیداست از این شیوه که مست است شرابت\r\nتیری که زدی بر دلم از غمزه خطا رفت\r\nتا باز چه اندیشه کند رأی صوابت\r\nهر ناله و فریاد که کردم نشنیدی\r\nپیداست نگارا که بلند است جنابت\r\nدور است سر آب از این بادیه هشدار\r\nتا غول بیابان نفریبد به سرابت\r\nتا در ره پیری به چه آیین روی ای دل\r\nباری به غلط صرف شد ایام شبابت\r\nای قصر دل افروز که منزلگه انسی\r\nیا رب مکناد آفت ایام خرابت\r\nحافظ نه غلامیست که از خواجه گریزد\r\nصلحی کن و بازآ که خرابم ز عتابت","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh15"},{"id":"ganjoor-hafez-16","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"خمی که ابروی شوخ تو در کمان انداخت\r\nبه قصد جان من زار ناتوان انداخت\r\nنبود نقش دو عالم که رنگ الفت بود\r\nزمانه طرح محبت نه این زمان انداخت\r\nبه یک کرشمه که نرگس به خودفروشی کرد\r\nفریب چشم تو صد فتنه در جهان انداخت\r\nشراب خورده و خوی کرده می روی به چمن\r\nکه آب روی تو آتش در ارغوان انداخت\r\nبه بزمگاه چمن دوش مست بگذشتم\r\nچو از دهان توام غنچه در گمان انداخت\r\nبنفشه طره مفتول خود گره می زد\r\nصبا حکایت زلف تو در میان انداخت\r\nز شرم آن که به روی تو نسبتش کردم\r\nسمن به دست صبا خاک در دهان انداخت\r\nمن از ورع می و مطرب ندیدمی زین پیش\r\nهوای مغبچگانم در این و آن انداخت\r\nکنون به آب می لعل خرقه می شویم\r\nنصیبه ازل از خود نمی توان انداخت\r\nمگر گشایش حافظ در این خرابی بود\r\nکه بخشش ازلش در می مغان انداخت\r\nجهان به کام من اکنون شود که دور زمان\r\nمرا به بندگی خواجه جهان انداخت","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh16"},{"id":"ganjoor-hafez-17","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"سینه از آتش دل در غم جانانه بسوخت\r\nآتشی بود در این خانه که کاشانه بسوخت\r\nتنم از واسطه دوری دلبر بگداخت\r\nجانم از آتش مهر رخ جانانه بسوخت\r\nسوز دل بین که ز بس آتش اشکم دل شمع\r\nدوش بر من ز سر مهر چو پروانه بسوخت\r\nآشنایی نه غریب است که دلسوز من است\r\nچون من از خویش برفتم دل بیگانه بسوخت\r\nخرقه زهد مرا آب خرابات ببرد\r\nخانه عقل مرا آتش میخانه بسوخت\r\nچون پیاله دلم از توبه که کردم بشکست\r\nهمچو لاله جگرم بی می و خمخانه بسوخت\r\nماجرا کم کن و بازآ که مرا مردم چشم\r\nخرقه از سر به درآورد و به شکرانه بسوخت\r\nترک افسانه بگو حافظ و می نوش دمی\r\nکه نخفتیم شب و شمع به افسانه بسوخت","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh17"},{"id":"ganjoor-hafez-18","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"ساقیا آمدن عید مبارک بادت\r\nوان مواعید که کردی مرود از یادت\r\nدر شگفتم که در این مدت ایام فراق\r\nبرگرفتی ز حریفان دل و دل می دادت\r\nبرسان بندگی دختر رز گو به درآی\r\nکه دم و همت ما کرد ز بند آزادت\r\nشادی مجلسیان در قدم و مقدم توست\r\nجای غم باد مر آن دل که نخواهد شادت\r\nشکر ایزد که ز تاراج خزان رخنه نیافت\r\nبوستان سمن و سرو و گل و شمشادت\r\nچشم بد دور کز آن تفرقه ات بازآورد\r\nطالع نامور و دولت مادرزادت\r\nحافظ از دست مده دولت این کشتی نوح\r\nور نه طوفان حوادث ببرد بنیادت","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh18"},{"id":"ganjoor-hafez-19","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"ای نسیم سحر آرامگه یار کجاست\r\nمنزل آن مه عاشق کش عیار کجاست\r\nشب تار است و ره وادی ایمن در پیش\r\nآتش طور کجا موعد دیدار کجاست\r\nهر که آمد به جهان نقش خرابی دارد\r\nدر خرابات بگویید که هشیار کجاست\r\nآن کس است اهل بشارت که اشارت داند\r\nنکته ها هست بسی محرم اسرار کجاست\r\nهر سر موی مرا با تو هزاران کار است\r\nما کجاییم و ملامت گر بی کار کجاست\r\nباز پرسید ز گیسوی شکن در شکنش\r\nکاین دل غم زده سرگشته گرفتار کجاست\r\nعقل دیوانه شد آن سلسله مشکین کو\r\nدل ز ما گوشه گرفت ابروی دلدار کجاست\r\nساقی و مطرب و می جمله مهیاست ولی\r\nعیش بی یار مهیا نشود یار کجاست\r\nحافظ از باد خزان در چمن دهر مرنج\r\nفکر معقول بفرما گل بی خار کجاست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh19"},{"id":"ganjoor-hafez-20","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"روزه یک سو شد و عید آمد و دل ها برخاست\r\nمی ز خم خانه به جوش آمد و می  باید خواست\r\nنوبه زهدفروشان گران جان بگذشت\r\nوقت رندی و طرب کردن رندان پیداست\r\nچه ملامت بود آن را که چنین باده خورد\r\nاین چه عیب است بدین بی خردی وین چه خطاست\r\nباده نوشی که در او روی و ریایی نبود\r\nبهتر از زهدفروشی که در او روی و ریاست\r\nما نه رندان ریاییم و حریفان نفاق\r\nآن که او عالم سر است بدین حال گواست\r\nفرض ایزد بگزاریم و به کس بد نکنیم\r\nوان چه گویند روا نیست نگوییم رواست\r\nچه شود گر من و تو چند قدح باده خوریم\r\nباده از خون رزان است نه از خون شماست\r\nاین چه عیب است کز آن عیب خلل خواهد بود\r\nور بود نیز چه شد مردم بی عیب کجاست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh20"},{"id":"ganjoor-hafez-21","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"دل و دینم شد و دلبر به ملامت برخاست\r\nگفت با ما منشین کز تو سلامت برخاست\r\nکه شنیدی که در این بزم دمی خوش بنشست\r\nکه نه در آخر صحبت به ندامت برخاست\r\nشمع اگر زان لب خندان به زبان لافی زد\r\nپیش عشاق تو شب ها به غرامت برخاست\r\nدر چمن باد بهاری ز کنار گل و سرو\r\nبه هواداری آن عارض و قامت برخاست\r\nمست بگذشتی و از خلوتیان ملکوت\r\nبه تماشای تو آشوب قیامت برخاست\r\nپیش رفتار تو پا برنگرفت از خجلت\r\nسرو سرکش که به ناز از قد و قامت برخاست\r\nحافظ این خرقه بینداز مگر جان ببری\r\nکآتش از خرقه سالوس و کرامت برخاست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh21"},{"id":"ganjoor-hafez-22","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"چو بشنوی سخن اهل دل مگو که خطاست\r\nسخن شناس نه ای جان من خطا این جاست\r\nسرم به دنیی و عقبی فرو نمی آید\r\nتبارک الله ازین فتنه ها که در سر ماست\r\nدر اندرون من خسته دل ندانم کیست\r\nکه من خموشم و او در فغان و در غوغاست\r\nدلم ز پرده برون شد کجایی ای مطرب\r\nبنال هان که از این پرده کار ما به نواست\r\nمرا به کار جهان هرگز التفات نبود\r\nرخ تو در نظر من چنین خوشش آراست\r\nنخفته ام ز خیالی که می پزد دل من\r\nخمار صد شبه دارم شراب خانه کجاست\r\nچنین که صومعه آلوده شد ز خون دلم\r\nگرم به باده بشویید حق به دست شماست\r\nاز آن به دیر مغانم عزیز می دارند\r\nکه آتشی که نمیرد همیشه در دل ماست\r\nچه ساز بود که در پرده می زد آن مطرب\r\nکه رفت عمر و هنوزم دماغ پر ز هواست\r\nندای عشق تو دیشب در اندرون دادند\r\nفضای سینه حافظ هنوز پر ز صداست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh22"},{"id":"ganjoor-hafez-23","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"خیال روی تو در هر طریق همره ماست\r\nنسیم موی تو پیوند جان آگه ماست\r\nبه رغم مدعیانی که منع عشق کنند\r\nجمال چهره تو حجت موجه ماست\r\nببین که سیب زنخدان تو چه می گوید\r\nهزار یوسف مصری فتاده در چه ماست\r\nاگر به زلف دراز تو دست ما نرسد\r\nگناه بخت پریشان و دست کوته ماست\r\nبه حاجب در خلوت سرای خاص بگو\r\nفلان ز گوشه نشینان خاک درگه ماست\r\nبه صورت از نظر ما اگر چه محجوب است\r\nهمیشه در نظر خاطر مرفه ماست\r\nاگر به سالی حافظ دری زند بگشای\r\nکه سال هاست که مشتاق روی چون مه ماست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh23"},{"id":"ganjoor-hafez-24","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"مطلب طاعت و پیمان و صلاح از من مست\r\nکه به پیمانه کشی شهره شدم روز الست\r\nمن همان دم که وضو ساختم از چشمه عشق\r\nچار تکبیر زدم یکسره بر هرچه که هست\r\nمی بده تا دهمت آگهی از سر قضا\r\nکه به روی که شدم عاشق و از بوی که مست\r\nکمر کوه کم است از کمر مور اینجا\r\nناامید از در رحمت مشو ای باده پرست\r\nبجز آن نرگس مستانه که چشمش مرساد\r\nزیر این طارم فیروزه کسی خوش ننشست\r\nجان فدای دهنش باد که در باغ نظر\r\nچمن آرای جهان خوشتر از این غنچه نبست\r\nحافظ از دولت عشق تو سلیمانی شد\r\nیعنی از وصل تواش نیست بجز باد به دست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh24"},{"id":"ganjoor-hafez-25","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"شکفته شد گل حمرا و گشت بلبل مست\r\nصلای سرخوشی ای صوفیان باده پرست\r\nاساس توبه که در محکمی چو سنگ نمود\r\nببین که جام زجاجی چه طرفه اش بشکست\r\nبیار باده که در بارگاه استغنا\r\nچه پاسبان و چه سلطان چه هوشیار و چه مست\r\nاز این رباط دو در چون ضرورت است رحیل\r\nرواق و طاق معیشت چه سربلند و چه پست\r\nمقام عیش میسر نمی شود بی رنج\r\nبلی به حکم بلا بسته اند عهد الست\r\nبه هست و نیست مرنجان ضمیر و خوش می باش\r\nکه نیستی ست سرانجام هر کمال که هست\r\nشکوه آصفی و اسب باد و منطق طیر\r\nبه باد رفت و از او خواجه هیچ طرف نبست\r\nبه بال و پر مرو از ره که تیر پرتابی\r\nهوا گرفت زمانی ولی به خاک نشست\r\nزبان کلک تو حافظ چه شکر آن گوید\r\nکه گفته سخنت می برند دست به دست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh25"},{"id":"ganjoor-hafez-26","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"زلف آشفته و خوی کرده و خندان لب و مست\r\nپیرهن چاک و غزل خوان و صراحی در دست\r\nنرگسش عربده جوی و لبش افسوس کنان\r\nنیم شب دوش به بالین من آمد بنشست\r\nسر فرا گوش من آورد به آواز حزین\r\nگفت ای عاشق دیرینه من خوابت هست\r\nعاشقی را که چنین باده شبگیر دهند\r\nکافر عشق بود گر نشود باده پرست\r\nبرو ای زاهد و بر دردکشان خرده مگیر\r\nکه ندادند جز این تحفه به ما روز الست\r\nآن چه او ریخت به پیمانه ما نوشیدیم\r\nاگر از خمر بهشت است وگر باده مست\r\nخنده جام می و زلف گره گیر نگار\r\nای بسا توبه که چون توبه حافظ بشکست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh26"},{"id":"ganjoor-hafez-27","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"در دیر مغان آمد یارم قدحی در دست\r\nمست از می و میخواران از نرگس مستش مست\r\nدر نعل سمند او شکل مه نو پیدا\r\nوز قد بلند او بالای صنوبر پست\r\nآخر به چه گویم هست از خود خبرم چون نیست\r\nوز بهر چه گویم نیست با وی نظرم چون هست\r\nشمع دل دمسازم بنشست چو او برخاست\r\nو افغان ز نظربازان برخاست چو او بنشست\r\nگر غالیه خوش بو شد در گیسوی او پیچید\r\nور وسمه کمانکش گشت در ابروی او پیوست\r\nبازآی که بازآید عمر شده حافظ\r\nهرچند که ناید باز تیری که بشد از شست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh27"},{"id":"ganjoor-hafez-28","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"به جان خواجه و حق قدیم و عهد درست\r\nکه مونس دم صبحم دعای دولت توست\r\nسرشک من که ز طوفان نوح دست برد\r\nز لوح سینه نیارست نقش مهر تو شست\r\nبکن معامله ای وین دل شکسته بخر\r\nکه با شکستگی ارزد به صد هزار درست\r\nزبان مور به آصف دراز گشت و رواست\r\nکه خواجه خاتم جم یاوه کرد و باز نجست\r\nدلا طمع مبر از لطف بی نهایت دوست\r\nچو لاف عشق زدی سر بباز چابک و چست\r\nبه صدق کوش که خورشید زاید از نفست\r\nکه از دروغ سیه روی گشت صبح نخست\r\nشدم ز دست تو شیدای کوه و دشت و هنوز\r\nنمی کنی به ترحم نطاق سلسله سست\r\nمرنج حافظ و از دلبر ان حفاظ مجوی\r\nگناه باغ چه باشد چو این گیاه نرست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh28"},{"id":"ganjoor-hafez-29","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"ما را ز خیال تو چه پروای شراب است\r\nخم گو سر خود گیر که خمخانه خراب است\r\nگر خمر بهشت است بریزید که بی دوست\r\nهر شربت عذبم که دهی عین عذاب است\r\nافسوس که شد دلبر و در دیده گریان\r\nتحریر خیال خط او نقش بر آب است\r\nبیدار شو ای دیده که ایمن نتوان بود\r\nزین سیل دمادم که در این منزل خواب است\r\nمعشوق عیان می گذرد بر تو ولیکن\r\nاغیار همی بیند از آن بسته نقاب است\r\nگل بر رخ رنگین تو تا لطف عرق دید\r\nدر آتش شوق از غم دل غرق گلاب است\r\nسبز است در و دشت بیا تا نگذاریم\r\nدست از سر آبی که جهان جمله سراب است\r\nدر کنج دماغم مطلب جای نصیحت\r\nکـ این گوشه پر از زمزمه چنگ و رباب است\r\nحافظ چه شد ار عاشق و رند است و نظرباز\r\nبس طور عجب لازم ایام شباب است","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh29"},{"id":"ganjoor-hafez-30","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"زلفت هزار دل به یکی تار مو ببست\r\nراه هزار چاره گر از چارسو ببست\r\nتا عاشقان به بوی نسیمش دهند جان\r\nبگشود نافه ای و در آرزو ببست\r\nشیدا از آن شدم که نگارم چو ماه نو\r\nابرو نمود و جلوه گری کرد و رو ببست\r\nساقی به چند رنگ می اندر پیاله ریخت\r\nاین نقش ها نگر که چه خوش در کدو ببست\r\nیا رب چه غمزه کرد صراحی که خون خم\r\nبا نعره های قلقلش اندر گلو ببست\r\nمطرب چه پرده ساخت که در پرده سماع\r\nبر اهل وجد و حال در های وهو ببست\r\nحافظ هر آن که عشق نورزید و وصل خواست\r\nاحرام طوف کعبه دل بی وضو ببست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh30"},{"id":"ganjoor-hafez-31","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"آن شب قدری که گویند اهل خلوت امشب است\r\nیا رب این تأثیر دولت در کدامین کوکب است\r\nتا به گیسوی تو دست ناسزایان کم رسد\r\nهر دلی از حلقه ای در ذکر یارب یارب است\r\nکشته چاه زنخدان توام کز هر طرف\r\nصد هزارش گردن جان زیر طوق غبغب است\r\nشهسوار من که مه آیینه دار روی اوست\r\nتاج خورشید بلندش خاک نعل مرکب است\r\nعکس خوی بر عارضش بین کآفتاب گرم رو\r\nدر هوای آن عرق تا هست هر روزش تب است\r\nمن نخواهم کرد ترک لعل یار و جام می\r\nزاهدان معذور داریدم که اینم مذهب است\r\nاندر آن ساعت که بر پشت صبا بندند زین\r\nبا سلیمان چون برانم من که مورم مرکب است\r\nآن که ناوک بر دل من زیر چشمی می زند\r\nقوت جان حافظش در خنده زیر لب است\r\nآب حیوانش ز منقار بلاغت می چکد\r\nزاغ کلک من بنامیزد چه عالی مشرب است","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh31"},{"id":"ganjoor-hafez-32","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"خدا چو صورت ابروی دلگشای تو بست\r\nگشاد کار من اندر کرشمه های تو بست\r\nمرا و سرو چمن را به خاک راه نشاند\r\nزمانه تا قصب نرگس قبای تو بست\r\nز کار ما و دل غنچه صد گره بگشود\r\nنسیم گل چو دل اندر پی هوای تو بست\r\nمرا به بند تو دوران چرخ راضی کرد\r\nولی چه سود که سررشته در رضای تو بست\r\nچو نافه بر دل مسکین من گره مفکن\r\nکه عهد با سر زلف گره گشای تو بست\r\nتو خود وصال دگر بودی ای نسیم وصال\r\nخطا نگر که دل امید در وفای تو بست\r\nز دست جور تو گفتم ز شهر خواهم رفت\r\nبه خنده گفت که حافظ برو که پای تو بست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh32"},{"id":"ganjoor-hafez-33","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"خلوت گزیده را به تماشا چه حاجت است\r\nچون کوی دوست هست به صحرا چه حاجت است\r\nجانا به حاجتی که تو را هست با خدا\r\nکآخر دمی بپرس که ما را چه حاجت است\r\nای پادشاه حسن خدا را بسوختیم\r\nآخر سؤال کن که گدا را چه حاجت است\r\nارباب حاجتیم و زبان سؤال نیست\r\nدر حضرت کریم تمنا چه حاجت است\r\nمحتاج قصه نیست گرت قصد خون ماست\r\nچون رخت از آن توست به یغما چه حاجت است\r\nجام جهان نماست ضمیر منیر دوست\r\nاظهار احتیاج خود آن جا چه حاجت است\r\nآن شد که بار منت ملاح بردمی\r\nگوهر چو دست داد به دریا چه حاجت است\r\nای مدعی برو که مرا با تو کار نیست\r\nاحباب حاضرند به اعدا چه حاجت است\r\nای عاشق گدا چو لب روح بخش یار\r\nمی داندت وظیفه تقاضا چه حاجت است\r\nحافظ تو ختم کن که هنر خود عیان شود\r\nبا مدعی نزاع و محاکا چه حاجت است","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh33"},{"id":"ganjoor-hafez-34","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"رواق منظر چشم من آشیانه توست\r\nکرم نما و فرود آ که خانه خانه توست\r\nبه لطف خال و خط از عارفان ربودی دل\r\nلطیفه های عجب زیر دام و دانه توست\r\nدلت به وصل گل ای بلبل صبا خوش باد\r\nکه در چمن همه گلبانگ عاشقانه توست\r\nعلاج ضعف دل ما به لب حوالت کن\r\nکه این مفرح یاقوت در خزانه توست\r\nبه تن مقصرم از دولت ملازمتت\r\nولی خلاصه جان خاک آستانه توست\r\nمن آن نیم که دهم نقد دل به هر شوخی\r\nدر خزانه به مهر تو و نشانه توست\r\nتو خود چه لعبتی ای شهسوار شیرین کار\r\nکه توسنی چو فلک رام تازیانه توست\r\nچه جای من که بلغزد سپهر شعبده باز\r\nاز این حیل که در انبانه بهانه توست\r\nسرود مجلست اکنون فلک به رقص آرد\r\nکه شعر حافظ شیرین سخن ترانه توست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh34"},{"id":"ganjoor-hafez-35","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"برو به کار خود ای واعظ این چه فریادست\r\nمرا فتاد دل از ره تو را چه افتادست\r\nمیان او که خدا آفریده است از هیچ\r\nدقیقه ای ست که هیچ آفریده نگشادست\r\nبه کام تا نرساند مرا لبش چون نای\r\nنصیحت همه عالم به گوش من بادست\r\nگدای کوی تو از هشت خلد مستغنی ست\r\nاسیر عشق تو از هر دو عالم آزادست\r\nاگر چه مستی عشقم خراب کرد ولی\r\nاساس هستی من زآن خراب آبادست\r\nدلا منال ز بیداد و جور یار که یار\r\nتو را نصیب همین کرد و این از آن دادست\r\nبرو فسانه مخوان و فسون مدم حافظ\r\nکز این فسانه و افسون مرا بسی یادست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh35"},{"id":"ganjoor-hafez-36","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"تا سر زلف تو در دست نسیم افتادست\r\nدل سودازده از غصه دو نیم افتادست\r\nچشم جادوی تو خود عین سواد سحر است\r\nلیکن این هست که این نسخه سقیم افتادست\r\nدر خم زلف تو آن خال سیه دانی چیست\r\nنقطه دوده که در حلقه جیم افتادست\r\nزلف مشکین تو در گلشن فردوس عذار\r\nچیست طاووس که در باغ نعیم افتادست\r\nدل من در هوس روی تو ای مونس جان\r\nخاک راهیست که در دست نسیم افتادست\r\nهمچو گرد این تن خاکی نتواند برخاست\r\nاز سر کوی تو زان رو که عظیم افتادست\r\nسایه قد تو بر قالبم ای عیسی دم\r\nعکس روحیست که بر عظم رمیم افتادست\r\nآن که جز کعبه مقامش نبد از یاد لبت\r\nبر در میکده دیدم که مقیم افتادست\r\nحافظ گمشده را با غمت ای یار عزیز\r\nاتحادیست که در عهد قدیم افتادست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh36"},{"id":"ganjoor-hafez-37","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"بیا که قصر امل سخت سست بنیادست\r\nبیار باده که بنیاد عمر بر بادست\r\nغلام همت آنم که زیر چرخ کبود\r\nز هر چه رنگ تعلق پذیرد آزادست\r\nچه گویمت که به میخانه دوش مست و خراب\r\nسروش عالم غیبم چه مژده ها دادست\r\nکه ای بلندنظر شاهباز سدره نشین\r\nنشیمن تو نه این کنج محنت آبادست\r\nتو را ز کنگره عرش می زنند صفیر\r\nندانمت که در این دامگه چه افتادست\r\nنصیحتی کنمت یاد گیر و در عمل آر\r\nکه این حدیث ز پیر طریقتم یادست\r\nغم جهان مخور و پند من مبر از یاد\r\nکه این لطیفه عشقم ز رهروی یادست\r\nرضا به داده بده وز جبین گره بگشای\r\nکه بر من و تو در اختیار نگشادست\r\nمجو درستی عهد از جهان سست نهاد\r\nکه این عجوز عروس هزاردامادست\r\nنشان عهد و وفا نیست در تبسم گل\r\nبنال بلبل بی دل که جای فریادست\r\nحسد چه می بری ای سست نظم بر حافظ\r\nقبول خاطر و لطف سخن خدادادست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh37"},{"id":"ganjoor-hafez-38","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"بی مهر رخت روز مرا نور نماندست\r\nوز عمر مرا جز شب دیجور نماندست\r\nهنگام وداع تو ز بس گریه که کردم\r\nدور از رخ تو چشم مرا نور نماندست\r\nمی رفت خیال تو ز چشم من و می گفت\r\nهیهات از این گوشه که معمور نماندست\r\nوصل تو اجل را ز سرم دور همی داشت\r\nاز دولت هجر تو کنون دور نماندست\r\nنزدیک شد آن دم که رقیب تو بگوید\r\nدور از رخت این خسته رنجور نماندست\r\nصبر است مرا چاره هجران تو لیکن\r\nچون صبر توان کرد که مقدور نماندست\r\nدر هجر تو گر چشم مرا آب روان است\r\nگو خون جگر ریز که معذور نماندست\r\nحافظ ز غم از گریه نپرداخت به خنده\r\nماتم زده را داعیه سور نماندست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh38"},{"id":"ganjoor-hafez-39","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"باغ مرا چه حاجت سرو و صنوبر است\r\nشمشاد خانه پرور ما از که کمتر است\r\nای نازنین پسر تو چه مذهب گرفته ای\r\nکت خون ما حلال تر از شیر مادر است\r\nچون نقش غم ز دور ببینی شراب خواه\r\nتشخیص کرده ایم و مداوا مقرر است\r\nاز آستان پیر مغان سر چرا کشیم\r\nدولت در آن سرا و گشایش در آن در است\r\nیک قصه بیش نیست غم عشق وین عجب\r\nکز هر زبان که می شنوم نامکرر است\r\nدی وعده داد وصلم و در سر شراب داشت\r\nامروز تا چه گوید و بازش چه در سر است\r\nشیراز و آب رکنی و این باد خوش نسیم\r\nعیبش مکن که خال رخ هفت کشور است\r\nفرق است از آب خضر که ظلمات جای او است\r\nتا آب ما که منبعش الله اکبر است\r\nما آبروی فقر و قناعت نمی بریم\r\nبا پادشه بگوی که روزی مقدر است\r\nحافظ چه طرفه شاخ نباتیست کلک تو\r\nکش میوه دلپذیرتر از شهد و شکر است","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh39"},{"id":"ganjoor-hafez-40","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"المنة لله که در میکده باز است\r\nزان رو که مرا بر در او روی نیاز است\r\nخم ها همه در جوش و خروش اند ز مستی\r\nوان می که در آن جاست حقیقت نه مجاز است\r\nاز وی همه مستی و غرور است و تکبر\r\nوز ما همه بیچارگی و عجز و نیاز است\r\nرازی که بر غیر نگفتیم و نگوییم\r\nبا دوست بگوییم که او محرم راز است\r\nشرح شکن زلف خم اندر خم جانان\r\nکوته نتوان کرد که این قصه دراز است\r\nبار دل مجنون و خم طره لیلی\r\nرخساره محمود و کف پای ایاز است\r\nبردوخته ام دیده چو باز از همه عالم\r\nتا دیده من بر رخ زیبای تو باز است\r\nدر کعبه کوی تو هر آن کس که بیاید\r\nاز قبله ابروی تو در عین نماز است\r\nای مجلسیان سوز دل حافظ مسکین\r\nاز شمع بپرسید که در سوز و گداز است","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh40"},{"id":"ganjoor-hafez-41","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"اگر چه باده فرح بخش و باد گل بیز است\r\nبه بانگ چنگ مخور می که محتسب تیز است\r\nصراحی ای و حریفی گرت به چنگ افتد\r\nبه عقل نوش که ایام فتنه  انگیز است\r\nدر آستین مرقع پیاله پنهان کن\r\nکه همچو چشم صراحی زمانه خونریز است\r\nبه آب دیده بشوییم خرقه ها از می\r\nکه موسم ورع و روزگار پرهیز است\r\nمجوی عیش خوش از دور باژگون سپهر\r\nکه صاف این سر خم جمله دردی آمیز است\r\nسپهر بر شده پرویزنی ست خون افشان\r\nکه ریزه اش سر کسری و تاج پرویز است\r\nعراق و فارس گرفتی به شعر خوش حافظ\r\nبیا که نوبت بغداد و وقت تبریز است","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh41"},{"id":"ganjoor-hafez-42","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"حال دل با تو گفتنم هوس است\r\nخبر دل شنفتنم هوس است\r\nطمع خام بین که قصه فاش\r\nاز رقیبان نهفتنم هوس است\r\nشب قدری چنین عزیز شریف\r\nبا تو تا روز خفتنم هوس است\r\nوه که دردانه ای چنین نازک\r\nدر شب تار سفتنم هوس است\r\nای صبا امشبم مدد فرمای\r\nکه سحرگه شکفتنم هوس است\r\nاز برای شرف به نوک مژه\r\nخاک راه تو رفتنم هوس است\r\nهمچو حافظ به رغم مدعیان\r\nشعر رندانه گفتنم هوس است","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh42"},{"id":"ganjoor-hafez-43","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"صحن بستان ذوق بخش و صحبت یاران خوش است\r\nوقت گل خوش باد کز وی وقت می خواران خوش است\r\nاز صبا هر دم مشام جان ما خوش می شود\r\nآری آری طیب انفاس هواداران خوش است\r\nناگشوده گل نقاب آهنگ رحلت ساز کرد\r\nناله  کن بلبل که گلبانگ دل افکاران خوش است\r\nمرغ خوشخوان را بشارت باد کاندر راه عشق\r\nدوست را با ناله شب های بیداران خوش است\r\nنیست در بازار عالم خوشدلی ور زان که هست\r\nشیوه رندی و خوش باشی عیاران خوش است\r\nاز زبان سوسن آزاده ام آمد به گوش\r\nکاندر این دیر کهن کار سبکباران خوش است\r\nحافظا ترک جهان گفتن طریق خوشدلیست\r\nتا نپنداری که احوال جهان داران خوش است","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh43"},{"id":"ganjoor-hafez-44","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"کنون که بر کف گل جام باده صاف است\r\nبه صد هزار زبان بلبلش در اوصاف است\r\nبخواه دفتر اشعار و راه صحرا گیر\r\nچه وقت مدرسه و بحث کشف کشاف است\r\nفقیه مدرسه دی مست بود و فتوی داد\r\nکه می حرام ولی به ز مال اوقاف است\r\nبه درد و صاف تو را حکم نیست خوش درکش\r\nکه هرچه ساقی ما کرد عین الطاف است\r\nببر ز خلق و چو عنقا قیاس کار بگیر\r\nکه صیت گوشه نشینان ز قاف تا قاف است\r\nحدیث مدعیان و خیال همکاران\r\nهمان حکایت زردوز و بوریاباف است\r\nخموش حافظ و این نکته های چون زر سرخ\r\nنگاه دار که قلاب شهر صراف است","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh44"},{"id":"ganjoor-hafez-45","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"در این زمانه رفیقی که خالی از خلل است\r\nصراحی می ناب و سفینه غزل است\r\nجریده رو که گذرگاه عافیت تنگ است\r\nپیاله گیر که عمر عزیز بی بدل است\r\nنه من ز بی عملی در جهان ملولم و بس\r\nملالت علما هم ز علم بی عمل است\r\nبه چشم عقل در این رهگذار پرآشوب\r\nجهان و کار جهان بی ثبات و بی محل است\r\nبگیر طره مه چهره ای و قصه مخوان\r\nکه سعد و نحس ز تأثیر زهره و زحل است\r\nدلم امید فراوان به وصل روی تو داشت\r\nولی اجل به ره عمر رهزن امل است\r\nبه هیچ دور نخواهند یافت هشیارش\r\nچنین که حافظ ما مست باده ازل است","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh45"},{"id":"ganjoor-hafez-46","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"گل در بر و می در کف و معشوق به کام است\r\nسلطان جهانم به چنین روز غلام است\r\nگو شمع میارید در این جمع که امشب\r\nدر مجلس ما ماه رخ دوست تمام است\r\nدر مذهب ما باده حلال است ولیکن\r\nبی روی تو ای سرو گل اندام حرام است\r\nگوشم همه بر قول نی و نغمه چنگ است\r\nچشمم همه بر لعل لب و گردش جام است\r\nدر مجلس ما عطر میامیز که ما را\r\nهر لحظه ز گیسو ی تو خوش بوی مشام است\r\nاز چاشنی قند مگو هیچ و ز شکر\r\nزآن رو که مرا از لب شیرین تو کام است\r\nتا گنج غمت در دل ویرانه  مقیم است\r\nهمواره مرا کوی خرابات مقام است\r\nاز ننگ چه گویی که مرا نام ز ننگ است\r\nوز نام چه پرسی که مرا ننگ ز نام است\r\nمی خواره و سرگشته و رندیم و نظرباز\r\nوآن کس که چو ما نیست در این شهر کدام است\r\nبا محتسبم عیب مگویید که او نیز\r\nپیوسته چو ما در طلب عیش مدام است\r\nحافظ منشین بی می و معشوق زمانی\r\nکایام گل و یاسمن و عید صیام است","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh46"},{"id":"ganjoor-hafez-47","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"به کوی میکده هر سالکی که ره دانست\r\nدری دگر زدن اندیشه تبه دانست\r\nزمانه افسر رندی نداد جز به کسی\r\nکه سرفرازی عالم در این کله دانست\r\nبر آستانه میخانه هر که یافت رهی\r\nز فیض جام می اسرار خانقه دانست\r\nهر آن که راز دو عالم ز خط ساغر خواند\r\nرموز جام جم از نقش خاک ره دانست\r\nورای طاعت دیوانگان ز ما مطلب\r\nکه شیخ مذهب ما عاقلی گنه دانست\r\nدلم ز نرگس ساقی امان نخواست به جان\r\nچرا که شیوه آن ترک دل سیه دانست\r\nز جور کوکب طالع سحرگهان چشمم\r\nچنان گریست که ناهید دید و مه دانست\r\nحدیث حافظ و ساغر که می زند پنهان\r\nچه جای محتسب و شحنه پادشه دانست\r\nبلندمرتبه شاهی که نه رواق سپهر\r\nنمونه ای ز خم طاق بارگه دانست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh47"},{"id":"ganjoor-hafez-48","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"صوفی از پرتو می راز نهانی دانست\r\nگوهر هر کس از این لعل توانی دانست\r\nقدر مجموعه گل مرغ سحر داند و بس\r\nکه نه هر کو ورقی خواند معانی دانست\r\nعرضه کردم دو جهان بر دل کارافتاده\r\nبه جز از عشق تو باقی همه فانی دانست\r\nآن شد اکنون که ز ابنای عوام اندیشم\r\nمحتسب نیز در این عیش نهانی دانست\r\nدل بر آسایش ما مصلحت وقت ندید\r\nور نه از جانب ما دل نگرانی دانست\r\nسنگ و گل را کند از یمن نظر لعل و عقیق\r\nهر که قدر نفس باد یمانی دانست\r\nای که از دفتر عقل آیت عشق آموزی\r\nترسم این نکته به تحقیق ندانی دانست\r\nمی بیاور که ننازد به گل باغ جهان\r\nهر که غارت گری باد خزانی دانست\r\nحافظ این گوهر منظوم که از طبع انگیخت\r\nز اثر تربیت آصف ثانی دانست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh48"},{"id":"ganjoor-hafez-49","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"روضه خلد برین خلوت درویشان است\r\nمایه محتشمی خدمت درویشان است\r\nگنج عزلت که طلسمات عجایب دارد\r\nفتح آن در نظر رحمت درویشان است\r\nقصر فردوس که رضوانش به دربانی رفت\r\nمنظری از چمن نزهت درویشان است\r\nآن چه زر می شود از پرتو آن قلب سیاه\r\nکیمیاییست که در صحبت درویشان است\r\nآن که پیشش بنهد تاج تکبر خورشید\r\nکبریاییست که در حشمت درویشان است\r\nدولتی را که نباشد غم از آسیب زوال\r\nبی تکلف بشنو دولت درویشان است\r\nخسروان قبله حاجات جهانند ولی\r\nسببش بندگی حضرت درویشان است\r\nروی مقصود که شاهان به دعا می طلبند\r\nمظهرش آینه طلعت درویشان است\r\nاز کران تا به کران لشکر ظلم است ولی\r\nاز ازل تا به ابد فرصت درویشان است\r\nای توانگر مفروش این همه نخوت که تو را\r\nسر و زر در کنف همت درویشان است\r\nگنج قارون که فرو می شود از قهر هنوز\r\nخوانده باشی که هم از غیرت درویشان است\r\nحافظ ار آب حیات ازلی می خواهی\r\nمنبعش خاک در خلوت درویشان است\r\nمن غلام نظر آصف عهدم کو را\r\nصورت خواجگی و سیرت درویشان است","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh49"},{"id":"ganjoor-hafez-50","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"به دام زلف تو دل مبتلای خویشتن است\r\nبکش به غمزه که اینش سزای خویشتن است\r\nگرت ز دست برآید مراد خاطر ما\r\nبه دست باش که خیری به جای خویشتن است\r\nبه جانت ای بت شیرین دهن که همچون شمع\r\nشبان تیره مرادم فنای خویشتن است\r\nچو رای عشق زدی با تو گفتم ای بلبل\r\nمکن که آن گل خندان به رای خویشتن است\r\nبه مشک چین و چگل نیست بوی گل محتاج\r\nکه نافه هاش ز بند قبای خویشتن است\r\nمرو به خانه ارباب بی مروت دهر\r\nکه گنج عافیتت در سرای خویشتن است\r\nبسوخت حافظ و در شرط عشقبازی او\r\nهنوز بر سر عهد و وفای خویشتن است","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh50"},{"id":"ganjoor-hafez-51","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"لعل سیراب به خون تشنه  لب یار من است\r\nوز پی دیدن او دادن جان کار من است\r\nشرم از آن چشم سیه بادش و مژگان دراز\r\nهر که دل بردن او دید و در انکار من است\r\nساروان رخت به دروازه مبر  کان سر کو\r\nشاهراهی ست که منزلگه دلدار من است\r\nبنده طالع خویشم که در این قحط وفا\r\nعشق آن لولی سرمست  خریدار من است\r\nطبله عطر گل و زلف عبیر افشانش\r\nفیض یک شمه ز بوی خوش عطار من است\r\nباغبان همچو نسیمم ز در خویش مران\r\nکآب گلزار تو از اشک چو گلنار من است\r\nشربت قند و گلاب از لب یارم فرمود\r\nنرگس او که طبیب دل بیمار من است\r\nآن که در طرز غزل نکته به حافظ آموخت\r\nیار شیرین سخن نادره گفتار من است","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh51"},{"id":"ganjoor-hafez-52","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"روزگاری ست که سودای بتان دین من است\r\nغم این کار  نشاط دل غمگین من است\r\nدیدن روی تو را دیده ی جان بین باید\r\nوین کجا مرتبه ی چشم جهان بین من است\r\nیار من باش که زیب فلک و زینت دهر\r\nاز مه روی تو و اشک چو پروین من است\r\nتا مرا عشق تو تعلیم سخن گفتن کرد\r\nخلق را ورد زبان مدحت و تحسین من است\r\nدولت فقر خدایا به من ارزانی دار\r\nکاین کرامت سبب حشمت و تمکین من است\r\nواعظ شحنه شناس این عظمت گو مفروش\r\nزان که منزلگه سلطان دل مسکین من است\r\nیا رب این کعبه ی مقصود تماشاگه کیست\r\nکه مغیلان طریقش گل و نسرین من است\r\nحافظ از حشمت پرویز دگر قصه مخوان\r\nکه لبش جرعه کش خسرو شیرین من است","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh52"},{"id":"ganjoor-hafez-53","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"منم که گوشه میخانه خانقاه من است\r\nدعای پیر مغان ورد صبحگاه من است\r\nگرم ترانه چنگ صبوح نیست چه باک\r\nنوای من به سحر آه عذرخواه من است\r\nز پادشاه و گدا فارغم بحمدالله\r\nگدای خاک در دوست پادشاه من است\r\nغرض ز مسجد و میخانه ام وصال شماست\r\nجز این خیال ندارم خدا گواه من است\r\nمگر به تیغ اجل خیمه برکنم ور نی\r\nرمیدن از در دولت نه رسم و راه من است\r\nاز آن زمان که بر این آستان نهادم روی\r\nفراز مسند خورشید تکیه گاه من است\r\nگناه اگرچه نبود اختیار ما حافظ\r\nتو در طریق ادب باش گو گناه من است","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh53"},{"id":"ganjoor-hafez-54","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"ز گریه مردم چشمم نشسته در خون است\r\nببین که در طلبت حال مردمان چون است\r\nبه یاد لعل تو و چشم مست میگونت\r\nز جام غم می لعلی که می خورم خون است\r\nز مشرق سر کو آفتاب طلعت تو\r\nاگر طلوع کند طالعم همایون است\r\nحکایت لب شیرین کلام فرهاد است\r\nشکنج طره لیلی مقام مجنون است\r\nدلم بجو که قدت همچو سرو دلجوی است\r\nسخن بگو که کلامت لطیف و موزون است\r\nز دور باده به جان راحتی رسان ساقی\r\nکه رنج خاطرم از جور دور گردون است\r\nاز آن دمی که ز چشمم برفت رود عزیز\r\nکنار دامن من همچو رود جیحون است\r\nچگونه شاد شود اندرون غمگینم\r\nبه اختیار که از اختیار بیرون است\r\nز بیخودی طلب یار می کند حافظ\r\nچو مفلسی که طلبکار گنج قارون است","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh54"},{"id":"ganjoor-hafez-55","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"خم زلف تو دام کفر و دین است\r\nز کارستان او یک شمه این است\r\nجمالت معجز حسن است لیکن\r\nحدیث غمزه ات سحر مبین است\r\nز چشم شوخ تو جان کی توان برد\r\nکه دایم با کمان اندر کمین است\r\nبر آن چشم سیه صد آفرین باد\r\nکه در عاشق کشی سحرآفرین است\r\nعجب علمیست علم هییت عشق\r\nکه چرخ هشتمش هفتم زمین است\r\nتو پنداری که بدگو رفت و جان برد\r\nحسابش با کرام الکاتبین است\r\nمشو حافظ ز کید زلفش ایمن\r\nکه دل برد و کنون در بند دین است","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh55"},{"id":"ganjoor-hafez-56","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"دل سراپرده محبت اوست\r\nدیده آیینه دار طلعت اوست\r\nمن که سر در نیاورم به دو کون\r\nگردنم زیر بار منت اوست\r\nتو و طوبی و ما و قامت یار\r\nفکر هر کس به قدر همت اوست\r\nگر من آلوده دامنم چه عجب\r\nهمه عالم گواه عصمت اوست\r\nمن که باشم در آن حرم که صبا\r\nپرده دار حریم حرمت اوست\r\nبی خیالش مباد منظر چشم\r\nزآن که این گوشه جای خلوت اوست\r\nهر گل نو که شد چمن آرای\r\nز اثر رنگ و بوی صحبت اوست\r\nدور مجنون گذشت و نوبت ماست\r\nهر کسی پنج روز نوبت اوست\r\nملکت عاشقی و گنج طرب\r\nهر چه دارم ز یمن همت اوست\r\nمن و دل گر فدا شدیم چه باک\r\nغرض اندر میان سلامت اوست\r\nفقر ظاهر مبین که حافظ را\r\nسینه گنجینه محبت اوست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh56"},{"id":"ganjoor-hafez-57","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"آن سیه چرده که شیرینی عالم با اوست\r\nچشم میگون لب خندان دل خرم با اوست\r\nگر چه شیرین  دهنان پادشهان اند ولی\r\nاو سلیمان زمان است که خاتم با اوست\r\nروی خوب است و کمال هنر و دامن پاک\r\nلاجرم همت پاکان دو عالم با اوست\r\nخال مشکین که بدان عارض گندمگون است\r\nسر آن دانه که شد رهزن آدم با اوست\r\nدلبرم عزم سفر کرد خدا را یاران\r\nچه کنم با دل مجروح که مرهم با اوست\r\nبا که این نکته توان گفت که آن سنگین  دل\r\nکشت ما را و دم عیسی مریم با اوست\r\nحافظ از معتقدان است گرامی دارش\r\nزآن که بخشایش بس روح مکرم با اوست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh57"},{"id":"ganjoor-hafez-58","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"سر ارادت ما و آستان حضرت دوست\r\nکه هر چه بر سر ما می رود ارادت اوست\r\nنظیر دوست ندیدم اگر چه از مه و مهر\r\nنهادم آینه ها در مقابل رخ دوست\r\nصبا ز حال دل تنگ ما چه شرح دهد\r\nکه چون شکنج ورق های غنچه تو بر توست\r\nنه من سبوکش این دیر رندسوزم و بس\r\nبسا سرا که در این کارخانه سنگ و سبوست\r\nمگر تو شانه زدی زلف عنبرافشان را\r\nکه باد غالیه سا گشت و خاک عنبربوست\r\nنثار روی تو هر برگ گل که در چمن است\r\nفدای قد تو هر سروبن که بر لب جوست\r\nزبان ناطقه در وصف شوق نالان است\r\nچه جای کلک بریده زبان بیهده گوست\r\nرخ تو در دلم آمد مراد خواهم یافت\r\nچرا که حال نکو در قفای فال نکوست\r\nنه این زمان دل حافظ در آتش هوس است\r\nکه داغدار ازل همچو لاله خودروست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh58"},{"id":"ganjoor-hafez-59","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"دارم امید عاطفتی از جناب دوست\r\nکردم جنایتی و امیدم به عفو اوست\r\nدانم که بگذرد ز سر جرم من که او\r\nگر چه پریوش است ولیکن فرشته خوست\r\nچندان گریستیم که هر کس که برگذشت\r\nدر اشک ما چو دید روان گفت کاین چه جوست\r\nهیچ است آن دهان و نبینم از او نشان\r\nموی است آن میان و ندانم که آن چه موست\r\nدارم عجب ز نقش خیالش که چون نرفت\r\nاز دیده ام که دم به دمش کار شست و شوست\r\nبی گفت و گوی زلف تو دل را همی کشد\r\nبا زلف دلکش تو که را روی گفت و گوست\r\nعمری ست تا ز زلف تو بویی شنیده ام\r\nزان بوی در مشام دل من هنوز بوست\r\nحافظ بد است حال پریشان تو ولی\r\nبر بوی زلف یار پریشانیت نکوست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh59"},{"id":"ganjoor-hafez-60","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"آن پیک نامور که رسید از دیار دوست\r\nآورد حرز جان ز خط مشکبار دوست\r\nخوش می دهد نشان جلال و جمال یار\r\nخوش می کند حکایت عز و وقار دوست\r\nدل دادمش به مژده و خجلت همی برم\r\nزین نقد قلب خویش که کردم نثار دوست\r\nشکر خدا که از مدد بخت کارساز\r\nبر حسب آرزوست همه کار و بار دوست\r\nسیر سپهر و دور قمر را چه اختیار\r\nدر گردشند بر حسب اختیار دوست\r\nگر باد فتنه هر دو جهان را به هم زند\r\nما و چراغ چشم و ره انتظار دوست\r\nکحل الجواهری به من آر ای نسیم صبح\r\nزان خاک نیکبخت که شد رهگذار دوست\r\nماییم و آستانه عشق و سر نیاز\r\nتا خواب خوش که را برد اندر کنار دوست\r\nدشمن به قصد حافظ اگر دم زند چه باک\r\nمنت خدای را که نیم شرمسار دوست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh60"},{"id":"ganjoor-hafez-61","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"صبا اگر گذری افتدت به کشور دوست\r\nبیار نفحه ای از گیسوی معنبر دوست\r\nبه جان او که به شکرانه جان برافشانم\r\nاگر به سوی من آری پیامی از بر دوست\r\nو گر چنان که در آن حضرتت نباشد بار\r\nبرای دیده بیاور غباری از در دوست\r\nمن گدا و تمنای وصل او هیهات\r\nمگر به خواب ببینم خیال منظر دوست\r\nدل صنوبری ام همچو بید لرزان است\r\nز حسرت قد و بالای چون صنوبر دوست\r\nاگر چه دوست به چیزی نمی خرد ما را\r\nبه عالمی نفروشیم مویی از سر دوست\r\nچه باشد ار شود از بند غم دلش آزاد\r\nچو هست حافظ مسکین غلام و چاکر دوست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh61"},{"id":"ganjoor-hafez-62","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"مرحبا ای پیک مشتاقان بده پیغام دوست\r\nتا کنم جان از سر رغبت فدای نام دوست\r\nواله و شیداست دایم همچو بلبل در قفس\r\nطوطی طبعم ز عشق شکر و بادام دوست\r\nزلف او دام است و خالش دانه آن دام و من\r\nبر امید دانه ای افتاده ام در دام دوست\r\nسر ز مستی برنگیرد تا به صبح روز حشر\r\nهر که چون من در ازل یک جرعه خورد از جام دوست\r\nبس نگویم شمه ای از شرح شوق خود از آنک\r\nدردسر باشد نمودن بیش از این ابرام دوست\r\nگر دهد دستم کشم در دیده همچون توتیا\r\nخاک راهی کـ آن مشرف گردد از اقدام دوست\r\nمیل من سوی وصال و قصد او سوی فراق\r\nترک کام خود گرفتم تا برآید کام دوست\r\nحافظ اندر درد او می سوز و بی درمان بساز\r\nزان که درمانی ندارد درد بی آرام دوست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh62"},{"id":"ganjoor-hafez-63","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"روی تو کس ندید و هزارت رقیب هست\r\nدر غنچه ای هنوز و صدت عندلیب هست\r\nگر آمدم به کوی تو چندان غریب نیست\r\nچون من در آن دیار هزاران غریب هست\r\nدر عشق خانقاه و خرابات فرق نیست\r\nهر جا که هست پرتو روی حبیب هست\r\nآن جا که کار صومعه را جلوه می دهند\r\nناقوس دیر راهب و نام صلیب هست\r\nعاشق که شد که یار به حالش نظر نکرد\r\nای خواجه درد نیست وگرنه طبیب هست\r\nفریاد حافظ این همه آخر به هرزه نیست\r\nهم قصه ای غریب و حدیثی عجیب هست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh63"},{"id":"ganjoor-hafez-64","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"اگر چه عرض هنر پیش یار بی ادبی ست\r\nزبان خموش ولیکن دهان پر از عربی ست\r\nپری نهفته رخ و دیو در کرشمه حسن\r\nبسوخت دیده ز حیرت که این چه بوالعجبی ست\r\nدر این چمن گل بی خار کس نچید آری\r\nچراغ مصطفوی با شرار بولهبی ست\r\nسبب مپرس که چرخ از چه سفله پرور شد\r\nکه کام بخشی او را بهانه بی سببی ست\r\nبه نیم جو نخرم طاق خانقاه و رباط\r\nمرا که مصطبه ایوان و پای خم طنبی ست\r\nجمال دختر رز نور چشم ماست مگر\r\nکه در نقاب زجاجی و پرده عنبی ست\r\nهزار عقل و ادب داشتم من ای خواجه\r\nکنون که مست خرابم صلاح بی ادبی ست\r\nبیار می که چو حافظ هزارم استظهار\r\nبه گریه سحری و نیاز نیم شبی ست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh64"},{"id":"ganjoor-hafez-65","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"خوش تر ز عیش و صحبت و باغ و بهار چیست\r\nساقی کجاست گو سبب انتظار چیست\r\nهر وقت خوش که دست دهد مغتنم شمار\r\nکس را وقوف نیست که انجام کار چیست\r\nپیوند عمر بسته به مویی ست هوش دار\r\nغمخوار خویش باش غم روزگار چیست\r\nمعنی آب زندگی و روضه ارم\r\nجز طرف جویبار و می خوشگوار چیست\r\nمستور و مست هر دو چو از یک قبیله اند\r\nما دل به عشوه که دهیم اختیار چیست\r\nراز درون پرده چه داند فلک خموش\r\nای مدعی نزاع تو با پرده دار چیست\r\nسهو و خطای بنده گرش اعتبار نیست\r\nمعنی عفو و رحمت آمرزگار چیست\r\nزاهد شراب کوثر و حافظ پیاله خواست\r\nتا در میانه خواسته کردگار چیست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh65"},{"id":"ganjoor-hafez-66","section":"poems","tags":["غزل","ادبیات کلاسیک","حافظ"],"author":"حافظ","body":"بنال بلبل اگر با منت سر یاری ست\r\nکه ما دو عاشق زاریم و کار ما زاری ست\r\nدر آن زمین که نسیمی وزد ز طره دوست\r\nچه جای دم زدن نافه های تاتاری ست\r\nبیار باده که رنگین کنیم جامه زرق\r\nکه مست جام غروریم و نام هشیاری ست\r\nخیال زلف تو پختن نه کار هر خامی ست\r\nکه زیر سلسله رفتن طریق عیاری ست\r\nلطیفه ای ست نهانی که عشق از او خیزد\r\nکه نام آن نه لب لعل و خط زنگاری ست\r\nجمال شخص نه چشم است و زلف و عارض و خال\r\nهزار نکته در این کار و بار دلداری ست\r\nقلندران حقیقت به نیم جو نخرند\r\nقبای اطلس آن کس که از هنر عاری ست\r\nبر آستان تو مشکل توان رسید آری\r\nعروج بر فلک سروری به دشواری ست\r\nسحر کرشمه چشمت به خواب می دیدم\r\nزهی مراتب خوابی که به ز بیداری ست\r\nدلش به ناله میازار و ختم کن حافظ\r\nکه رستگاری جاوید در کم آزاری ست","source":"گنجور","sourceUrl":"https://ganjoor.net/hafez/ghazal/sh66"}];
const norm=s=>String(s||"").normalize("NFKC").replace(/[\s\p{P}\p{S}\u200c\u200e\u200fـ]/gu,"").toLowerCase();
const seen=new Set((window.poemEntries||[]).map(x=>norm(x.body)));
for(const x of rows){const k=norm(x.body);if(k&&!seen.has(k)){seen.add(k);window.poemEntries.push(x);}}
})();
